import{_ as t,a as s}from"./chunks/built-with-blockly-badge-black.BLndjqRJ.js";import{_ as a,o as n,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const i="/assets/blocks-for-ha/ui/fr.png",f=JSON.parse('{"title":"Blocks for HA","description":"Créer visuellement des automatisations Home Assistant avec Blockly, YAML et Jinja.","frontmatter":{"title":"Blocks for HA","description":"Créer visuellement des automatisations Home Assistant avec Blockly, YAML et Jinja."},"headers":[],"relativePath":"fr/projects/blocks-for-ha/index.md","filePath":"fr/projects/blocks-for-ha/index.md","lastUpdated":1792852622000}'),l={name:"fr/projects/blocks-for-ha/index.md"};function c(u,e,d,p,m,g){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="blocks-for-ha" tabindex="-1">Blocks for HA <a class="header-anchor" href="#blocks-for-ha" aria-label="Permalink to &quot;Blocks for HA&quot;">​</a></h1><p>Nouveau en <strong>0.1.66</strong> : textes d’exemple inutiles supprimés dans toutes les catégories, notamment MQTT, objets, listes, conversions et valeurs de remplacement. Réponses Assist et texte Jinja vides sur une ligne. Séparateurs, structures JSON valides, réglages techniques et valeurs des projets existants conservés.</p><p>Nouveau en <strong>0.1.65</strong> : champ texte sur une ligne sans ligne d’aide, nouveaux textes vides et aucun bloc Bonjour prébranché dans Créer du texte avec. Texte existant conservé.</p><p>Nouveau en <strong>0.1.64</strong> : Templates par usage pour texte, plage horaire, variation et résultats si/sinon typés. Code Jinja libre une seule fois dans Templates. Commandes d’applications et d’automatisations sur deux lignes comme ioBroker. DE/EN/FR complets. <a href="./system-template">Guide et images</a>.</p><p>Nouveau en <strong>0.1.63</strong> : entrées de valeurs typées directes dans Template, comme Écrire un fichier dans ioBroker, avec ajout automatique d’une entrée. Sans engrenages sur les blocs Template. Les anciennes chaînes sont converties au chargement. <a href="./system-template">Guide</a>.</p><p>Nouveau en <strong>0.1.62</strong> : ID et valeurs d’entités partagées dans Système, instantané unique, commandes d’applications et d’automatisations, constructeur visuel de Templates. Relier texte, mathématiques, variables et valeurs système ; ajouter formatage, remplacement, nouvelle ligne et sortie conditionnelle. Clic droit pour Jinja et aperçu HA. DE/EN/FR. <a href="./system-template">Guide</a>.</p><p>Nouveau en <strong>0.1.61</strong> : blocs <strong>et / ou / non</strong> séparés. Ajouter, retirer et ordonner les champs HA facultatifs par engrenage. Champs obligatoires et valeurs importées conservés. DE/EN/FR. <a href="./advanced">Blocs examinés et utilisation</a>.</p><p>Nouveau en <strong>0.1.60</strong> : <strong>Horaire</strong> avec dialogue Assistant/Simple/CRON, onglets et secondes facultatives, jours, données du déclencheur et décalage solaire. Déclencheurs HA natifs avancés directement dans <strong>Déclencheurs</strong>. DE/EN/FR. <a href="./time">Comparaison ioBroker et limites</a>.</p><p>Nouveau en <strong>0.1.59</strong> : libellés et éditeurs proches d’ioBroker, <strong>Commentaire</strong> dans Système avec commentaires YAML et <strong>Message MQTT</strong> dans Messages sans sélection d’instance. Textes et images en DE/EN/FR. <a href="./blocks">Détails et images</a>.</p><h2 id="demarrage-vide-depuis-0-1-52" tabindex="-1">Démarrage vide depuis 0.1.52 <a class="header-anchor" href="#demarrage-vide-depuis-0-1-52" aria-label="Permalink to &quot;Démarrage vide depuis 0.1.52&quot;">​</a></h2><p>Depuis <strong>0.1.54</strong>, <strong>Nouvelle automatisation</strong> propose <strong>Enregistrer et recommencer</strong>, <strong>Recommencer sans enregistrer</strong> ou <strong>Annuler</strong>. Avant de vider l’éditeur, la sauvegarde est téléchargée au format <code>.blocks.json</code> avec les blocs, les données d’automatisation et le YAML collé. <strong>Ouvrir le projet</strong> permet de la restaurer. Annuler ou Échap conserve le travail actuel. Recommencer réinitialise les blocs, l’historique d’annulation, le nom, la description et les champs. La langue, l’apparence, la connexion HA et les paquets de blocs installés restent disponibles.</p><p>Sans projet enregistré, l’éditeur démarre entièrement vide. Glisser <strong>Automation</strong> depuis <strong>Système</strong> dans l’espace de travail ou importer du YAML. L’import dans un éditeur vide ne nécessite pas « Remplacer complètement l’automatisation actuelle ». Les exemples s’ouvrent uniquement avec <strong>Charger l’exemple</strong>.</p><p>Les projets enregistrés sont restaurés au démarrage suivant. Un projet vide reste vide après rechargement ou changement de langue. Si le projet local ne peut pas être chargé, l’éditeur s’ouvre vide avec un avertissement, sans exemple.</p><p>Nouveau en <strong>0.1.47</strong> : <a href="./blockly-audit">fonctions d’action avec paramètres et valeurs de retour conditionnelles</a>. Le catalogue prend désormais en charge 166 types de blocs.</p><p>Nouveau en <strong>0.1.46</strong> : <strong>Langue → Système / DE / EN / FR</strong> concerne toute l’interface, les dialogues, états, confirmations et messages de validation. Noms personnels, données d’entités, libellés des paquets et YAML/Jinja ne sont pas traduits automatiquement.</p><p><img src="'+i+'" alt="Interface française ; données de test et noms personnels conservés dans leur langue d’origine"></p><p>Nouveau en <strong>0.1.45</strong> : quatre doublons retirés de la boîte à outils. Nombre uniquement dans Mathématiques, texte dans Texte, couleur dans Couleur, groupe ET/OU/NON dans Logique. Valeurs contient le pourcentage ; projets existants compatibles.</p><p>Nouveau en <strong>0.1.44</strong> : sélection avec recherche des actions et cibles, cinq types de cibles, choix multiple et saisie Jinja. <a href="./entities">Utilisation et limites</a>.</p><p>Nouveau en <strong>0.1.42</strong> : trois boutons compacts de même taille pour l’import YAML, avec des libellés sur deux lignes si nécessaire. <strong>Eingabefeld leeren</strong>, à droite, efface le texte collé et l’erreur d’import. L’automatisation actuelle et la case de remplacement sont conservées.</p><p>Nouveau en <strong>0.1.41</strong> : 15 types de blocs Jinja imbriqués, 163 types au total. Modifier entités, filtres, comparaisons, calculs et modèles if/else/for simples. Texte exact conservé jusqu’à modification ; modèles non pris en charge conservés en blocs originaux. <a href="./advanced#jinja-experimental">Décomposition et limites</a>.</p><p>Depuis <strong>0.1.40</strong>, tous les thèmes utilisent une <strong>police de 16 px</strong>. Le menu de blocs reste à <strong>100 %</strong> : ajustement, molette et zoom modifient uniquement l’espace de travail. Zoom initial 100 %, ajustement 85–120 %, zoom manuel 50–240 %. Les grandes automatisations restent défilables ; l’ajustement ne descend pas sous 85 % afin de préserver la lisibilité. Vérifié en Full HD, 2560 px et HiDPI.</p><p>Nouveau en <strong>0.1.39</strong> : 148 types, déclencheurs/conditions HA avancés, cibles/variables/options, attente, branches parallèles, groupes d’actions et <strong>Jinja (expérimental)</strong> avec reconnaissance et texte original conservé. <a href="./advanced">Guide, limites et sources</a>.</p><p>Blocks for HA assemble des automatisations Home Assistant avec des blocs visuels. Les déclencheurs, conditions et actions produisent du YAML natif ; les expressions utilisent Jinja dans Home Assistant. Blockly fournit l’éditeur, pas le moteur d’exécution de HA.</p><p><strong>Version 0.1.47 · 166 types de blocs · code source Apache-2.0</strong></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/blocks_for_ha" target="_blank" rel="noreferrer">Code source sur GitHub</a> · <a href="/projects/blocks-for-ha/">Documentation DE</a> · <a href="/en/projects/blocks-for-ha/">Documentation EN</a></p><h2 id="langue-de-l-application" tabindex="-1">Langue de l’application <a class="header-anchor" href="#langue-de-l-application" aria-label="Permalink to &quot;Langue de l’application&quot;">​</a></h2><p>Le sélecteur <strong>Langue</strong> propose <strong>Langue du système</strong>, <strong>Deutsch (DE)</strong>, <strong>English (EN)</strong> et <strong>Français (FR)</strong>. Le mode système utilise les langues préférées du navigateur, y compris les variantes comme <code>fr-CA</code> ou <code>de-CH</code>. Si aucune langue prise en charge n’est trouvée, l’anglais est utilisé.</p><p>Ce choix concerne toute l’application : commandes, libellés, menus déroulants, infobulles, catégories, recherche et dialogues, notamment la création de variables. La préférence est locale à ce navigateur et indépendante des thèmes.</p><p>Un changement sauvegarde le projet puis recharge l’éditeur. Terminer les blocs incomplets avant de changer de langue. Si le stockage du navigateur est indisponible, l’éditeur conserve les blocs et refuse le rechargement. Les IDs d’entités, noms de variables, textes saisis, modèles, paramètres et YAML ne sont pas traduits. Les blocs des paquets personnalisés conservent la langue définie par leur auteur.</p><p>Les captures du <a href="./blocks">catalogue des blocs</a> sont générées avec les véritables blocs français. Les pages DE et EN utilisent leurs propres images.</p><h2 id="installation-et-connexion" tabindex="-1">Installation et connexion <a class="header-anchor" href="#installation-et-connexion" aria-label="Permalink to &quot;Installation et connexion&quot;">​</a></h2><p>L’application est distribuée dans le <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons" target="_blank" rel="noreferrer">dépôt des applications HA UGSo</a>. Elle peut aussi être lancée localement depuis <code>blocks_for_ha</code> avec <code>npm install</code> puis <code>npm run dev</code> sur <code>http://127.0.0.1:4180/</code>. Pour compiler : <code>npm run build</code>.</p><p>Dans HA, ouvrir l’application via Ingress. La connexion aux entités utilise le service serveur supervisé, sans transmettre de jeton HA au navigateur. Hors HA, l’éditeur fonctionne avec saisie manuelle des IDs. Voir <a href="./entities">Entités</a>.</p><h2 id="construire-une-automatisation" tabindex="-1">Construire une automatisation <a class="header-anchor" href="#construire-une-automatisation" aria-label="Permalink to &quot;Construire une automatisation&quot;">​</a></h2><ol><li>Donner un nom à l’automatisation et choisir son mode : <code>single</code>, <code>restart</code>, <code>queued</code> ou <code>parallel</code>. Les deux derniers proposent une limite maximale.</li><li>Placer les déclencheurs orange dans <strong>Quand</strong>, les conditions violettes dans <strong>Seulement si</strong>, puis les actions bleues dans <strong>Alors</strong>.</li><li>Rechercher ou saisir les IDs des entités. Remplacer les IDs d’exemple par ceux de son installation.</li><li>Vérifier le YAML et les diagnostics. Un indicateur valide vérifie la structure ; il ne confirme pas la disponibilité des services ou entités dans HA.</li><li>Copier le format <strong>Einzelne Automation · HA-Editor</strong> dans l’éditeur d’automatisation HA, via <strong>Modifier en YAML</strong>. Enregistrer et vérifier dans HA.</li></ol><p>Les connexions sont typées : un déclencheur ne peut pas rejoindre une chaîne d’actions. Les valeurs numériques fixes et celles calculées à l’exécution ont des usages différents. Les blocs isolés ou incomplets peuvent empêcher l’export au lieu d’être ignorés.</p><h2 id="importer-et-sauvegarder" tabindex="-1">Importer et sauvegarder <a class="header-anchor" href="#importer-et-sauvegarder" aria-label="Permalink to &quot;Importer et sauvegarder&quot;">​</a></h2><p><strong>Kopieren</strong> copie le YAML ; <strong>Speichern</strong> télécharge un fichier YAML nommé d’après l’automatisation. <strong>Öffnen</strong> lit un fichier pris en charge. Le format liste contient une seule automatisation. L’import ne convertit pas arbitrairement tout le YAML Home Assistant : les éléments non représentables sont refusés.</p><p>Pour coller du YAML, choisir <strong>YAML → Code importieren</strong>. Le panneau de sortie devient une zone de saisie ; <strong>Importieren</strong> remplace le bouton de sauvegarde. Taille maximale : <strong>1 Mo en UTF-8</strong>.</p><ul><li>Sans coche, l’import ajoute les déclencheurs, conditions et actions au projet valide actuel. Les conditions sont combinées avec ET ; les déclencheurs ajoutés peuvent entraîner davantage d’exécutions. Nom et réglages actuels sont conservés.</li><li>Avec <strong>Aktuelle Automation vollständig ersetzen</strong>, une confirmation demande de remplacer tous les blocs. Après acceptation, les métadonnées et blocs importés remplacent le projet. Annulation ou erreur : état précédent conservé.</li></ul><p><strong>Projekt sichern</strong> télécharge le projet JSON complet, avec disposition et définitions des paquets utilisés. <strong>Projekt öffnen</strong> restaure ce projet. Le dernier état est également enregistré localement dans le navigateur. Cette sauvegarde locale ne remplace pas un fichier de sauvegarde.</p><h2 id="espace-de-travail" tabindex="-1">Espace de travail <a class="header-anchor" href="#espace-de-travail" aria-label="Permalink to &quot;Espace de travail&quot;">​</a></h2><p>Les commandes permettent d’annuler/rétablir, d’ajuster la vue et de chercher les blocs déjà placés. La recherche de la boîte à outils, en bas du menu, cherche les blocs disponibles. <code>Ctrl+F</code> ou <code>Cmd+F</code> dans Blockly ouvre la recherche de l’espace de travail ; Entrée/Maj+Entrée parcourt les résultats, Échap ferme la recherche. Le bouton <strong>?</strong> affiche les raccourcis de navigation.</p><p>Le panneau YAML peut être replié vers la droite ; l’éditeur récupère sa largeur. Le réglage est enregistré localement. Sur petit écran, le panneau replié forme une barre sous l’éditeur. Aucun changement du projet ou du YAML.</p><p>Le thème de l’application <strong>Hell / Dunkel / System</strong> est indépendant des palettes Blockly <strong>UGSo Standard / Dark / Modern / Tritanopia</strong>. Voir <a href="./themes">Thèmes et zoom</a>.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sujet</th><th>Guide</th></tr></thead><tbody><tr><td>Tous les types, images et fonctions</td><td><a href="./blocks">Catalogue des blocs</a></td></tr><tr><td>Dates, comparaisons d’heure, soleil</td><td><a href="./time">Date et heure</a></td></tr><tr><td>Nombres, booléens, dates, JSON</td><td><a href="./conversion">Conversion</a></td></tr><tr><td>Délais, objets, conditions et choix</td><td><a href="./flow">Délais, objets et logique</a></td></tr><tr><td>Calculs, textes, listes et boucles</td><td><a href="./collections">Mathématiques, textes, listes et boucles</a></td></tr><tr><td>Différences Blockly/ioBroker/HA</td><td><a href="./blockly-audit">Comparaison et fonctions</a></td></tr><tr><td>Connexion en lecture aux entités</td><td><a href="./entities">Entités</a></td></tr><tr><td>Éditeur de paquets JSON/ZIP</td><td><a href="./custom-blocks">Blocs personnalisés</a></td></tr><tr><td>Code copiable et téléchargements</td><td><a href="./catalog/">Catalogue des paquets</a></td></tr></tbody></table><h2 id="limites-et-direction" tabindex="-1">Limites et direction <a class="header-anchor" href="#limites-et-direction" aria-label="Permalink to &quot;Limites et direction&quot;">​</a></h2><p>Les scripts ioBroker ne sont pas exécutés dans HA. Les intervalles nommés, <code>sendTo</code>, objets ioBroker et JSONata nécessiteraient une adaptation réelle. Le navigateur ne simule pas ces capacités. Les actions sont exécutées uniquement après utilisation du YAML dans Home Assistant.</p><p>Les prochaines possibilités comprennent la sélection des services et appareils HA, les variables typées, davantage de formes dans l’éditeur de blocs personnalisés et la gestion des versions de paquets. Le Block Factory original reste une référence ; ses définitions JSON seules ne contiennent pas un générateur HA complet.</p><h2 id="licences" tabindex="-1">Licences <a class="header-anchor" href="#licences" aria-label="Permalink to &quot;Licences&quot;">​</a></h2><p>Projet communautaire indépendant, sans affiliation officielle à Home Assistant ou Blockly. Blockly est une bibliothèque de la Raspberry Pi Foundation, initialement développée chez Google. Les dépendances sont intégrées localement ; aucune bibliothèque Blockly n’est chargée depuis un CDN. Blockly et ses plugins : Apache-2.0 ; YAML : ISC ; fflate : MIT. Les notices sont incluses dans l’application.</p><p><a class="blockly-attribution" href="https://www.blockly.com/" target="_blank" rel="noopener noreferrer"><img class="badge-light" src="'+t+'" alt="Built with Blockly" width="87" height="32"><img class="badge-dark" src="'+s+'" alt="Built with Blockly" width="87" height="32"></a></p><p>Depuis <strong>0.1.28</strong> : <strong>États en liste JSON</strong>, par exemple <code>[&quot;1_single&quot;,&quot;1_double&quot;]</code> ; IDs facultatifs dans tous les déclencheurs standard ; <strong>Déclenché par ID</strong> comme condition native (ID individuel ou liste JSON). Les actions HA génériques acceptent <strong>Cibles en liste JSON</strong>, des métadonnées facultatives et conservent explicitement les données vides. Les automatisations à quatre boutons et quatre branches <code>choose</code> sont entièrement importables.</p><p>La sortie <strong>Automatisation individuelle · Éditeur HA</strong> omet l’<code>id</code> principal. Les IDs des déclencheurs restent présents. Les projets et la sortie <strong>liste automations.yaml</strong> conservent l’ID existant de l’automatisation.</p><p><a href="https://www.home-assistant.io/docs/automation/trigger/#trigger-id" target="_blank" rel="noreferrer">Home Assistant: Trigger IDs</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#trigger-condition" target="_blank" rel="noreferrer">Trigger condition</a></p><p>Depuis <strong>0.1.29</strong>, l’espace Blockly occupe toute la hauteur du panneau jusqu’à la légende. Un panneau YAML plus haut agrandit aussi l’espace de travail ; la sortie reste repliable.</p><p>Depuis <strong>0.1.30</strong> : activer <strong>Heures en liste JSON</strong> pour plusieurs heures fixes, par exemple <code>[&quot;10:00:00&quot;,&quot;13:00:00&quot;,&quot;19:00:00&quot;]</code>. <strong>Tout changement</strong> omet <code>to</code> ; <strong>Entités en liste JSON</strong> surveille plusieurs entités. Sans <code>to</code>, HA réagit aussi aux changements d’attributs. Les événements acceptent par exemple <code>timer.finished</code> avec un filtre de données JSON facultatif. Les conditions horaires natives conservent <code>before</code>/<code>after</code> : heures fixes, après inclusif et avant exclusif, même à travers minuit. Des bornes identiques couvrent toute la journée. Assistants horaires, modèles horaires et filtres de jours restent hors de l’import pris en charge. L’automatisation complète conserve le modèle multiligne du minuteur et les branches <code>choose</code> imbriquées.</p><p><a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">Home Assistant: triggers</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#time-condition" target="_blank" rel="noreferrer">Time condition</a></p><p>Depuis <strong>0.1.31</strong>, le nouveau bloc prend en charge temperature.changed natif. Cible (JSON) : entity_id texte ou liste. Seuil (JSON) : type any, above, below, between ou outside. any exige seulement type ; above/below exigent value, between/outside value_min et value_max. Nombres : number et unit_of_measurement (°C/°F). Références : entity (sensor, number ou input_number). ID facultatif. Autres cibles (zone/appareil/étiquette) non prises en charge. Les topics MQTT, qos/retain/evaluate_payload et contenus JSON/Jinja multilignes restent présents.</p><p><a href="https://www.home-assistant.io/triggers/temperature.changed/" target="_blank" rel="noreferrer">Home Assistant: temperature.changed</a></p><p><strong>0.1.32:</strong> Calendriers et variables de réponse. <a href="./blocks">→</a></p><p><strong>0.1.33:</strong> Déclencheurs numériques avec durée de maintien. <a href="./blocks">→</a></p><p><strong>0.1.34:</strong> Plusieurs variables dans une action. <a href="./blocks">→</a></p><p><strong>0.1.35:</strong> Délai en texte ou modèle. <a href="./blocks">→</a></p><p><strong>0.1.36:</strong> Noms d’action HA dynamiques. <a href="./blocks">→</a></p><p><strong>0.1.37:</strong> <a href="./blocks">Déclencheur de motif horaire</a>.</p><p><strong>0.1.38:</strong> <a href="./blocks">Entités cibles dynamiques</a>.</p>',68)])])}const b=a(l,[["render",c]]);export{f as __pageData,b as default};
